package com.collegewise.entity;
import jakarta.persistence.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"college_id","course_id","placement_year"}))
public class Placement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private College college; @ManyToOne(fetch=FetchType.LAZY) private Course course; @Column(name="placement_year") private Integer year; private Integer studentsPlaced; private Integer studentsEligible; private Double averagePackage; private Double highestPackage; protected Placement(){} public Placement(College college,Course course,Integer year,Integer placed,Integer eligible,Double average,Double highest){this.college=college;this.course=course;this.year=year;this.studentsPlaced=placed;this.studentsEligible=eligible;this.averagePackage=average;this.highestPackage=highest;} public Long getId(){return id;} public College getCollege(){return college;} public Course getCourse(){return course;} public Integer getYear(){return year;} public Integer getStudentsPlaced(){return studentsPlaced;} public Integer getStudentsEligible(){return studentsEligible;} public Double getAveragePackage(){return averagePackage;} public Double getHighestPackage(){return highestPackage;} public void updateFrom(Placement p){this.college=p.college;this.course=p.course;this.year=p.year;this.studentsPlaced=p.studentsPlaced;this.studentsEligible=p.studentsEligible;this.averagePackage=p.averagePackage;this.highestPackage=p.highestPackage;} }
